arguments:
'
import pcbnew, json, sys
' + GEOMETRY_HELPER + '

params = json.loads(open(sys.argv[1]).read())

board = pcbnew.LoadBoard(params["pcb_path"])
if board is None:
    print(json.dumps({"error": "Failed to load board: " + str(params["pcb_path"])}))
    sys.exit(0)
silk_layer_ids = [board.GetLayerID("F.SilkS"), board.GetLayerID("B.SilkS")]

all_pads = []
for fp in board.GetFootprints():
    for pad in fp.Pads():
        sz = pad.GetBoundingBox()
        all_pads.append({
            "reference": fp.GetReference(),
            "x_min": sz.GetX(), "y_min": sz.GetY(),
            "x_max": sz.GetRight(), "y_max": sz.GetBottom(),
        })

all_silk = []
for fp in board.GetFootprints():
    _ref = fp.GetReference()
    for _ft, _fo in [("reference", fp.Reference()), ("value", fp.Value())]:
        if not _fo.IsVisible() or _fo.GetLayer() not in silk_layer_ids:
            continue
        all_silk.append({"component": _ref, "obj": _fo, "layer": _fo.GetLayer()})
for drawing in board.GetDrawings():
    if hasattr(drawing, 'GetText') and drawing.GetLayer() in silk_layer_ids:
        _vis = drawing.IsVisible() if hasattr(drawing, 'IsVisible') else True
        if _vis:
            all_silk.append({"component": None, "obj": drawing, "layer": drawing.GetLayer()})

if hasattr(board, 'GetBoardEdgesBoundingBox'):
    board_bb = board.GetBoardEdgesBoundingBox()
    board_valid = board_bb.GetWidth() > 0
else:
    board_bb = None
    board_valid = False

def _bbox_to_tuple(b):
    return (b.GetX(), b.GetY(), b.GetRight(), b.GetBottom())

def has_pad_overlap(text_bbox, own_ref):
    text_t = _bbox_to_tuple(text_bbox)
    for pad in all_pads:
        if pad["reference"] == own_ref:
            continue
        if aabb_overlap(text_t, (pad["x_min"], pad["y_min"], pad["x_max"], pad["y_max"])):
            return True
    return False

def has_text_overlap(text_bbox, own_ref, own_layer, own_obj):
    text_t = _bbox_to_tuple(text_bbox)
    for si in all_silk:
        if si["obj"] is own_obj:
            continue
        if si["component"] is not None and si["component"] == own_ref:
            continue
        if si["layer"] != own_layer:
            continue
        visible = si["obj"].IsVisible() if hasattr(si["obj"], 'IsVisible') else True
        if not visible:
            continue
        if aabb_overlap(text_t, _bbox_to_tuple(si["obj"].GetBoundingBox())):
            return True
    return False

def has_any_overlap(text_bbox, own_ref, own_layer, own_obj):
    return has_pad_overlap(text_bbox, own_ref) or has_text_overlap(text_bbox, own_ref, own_layer, own_obj)

def in_board(text_bbox):
    if not board_valid:
        return True
    return aabb_inside(_bbox_to_tuple(text_bbox), _bbox_to_tuple(board_bb))

MARGIN = pcbnew.FromMM(0.3)
moved = 0; hidden_count = 0

for fp in board.GetFootprints():
    ref = fp.GetReference()
    for field_type, field_obj in [("reference", fp.Reference()), ("value", fp.Value())]:
        if not field_obj.IsVisible() or field_obj.GetLayer() not in silk_layer_ids:
            continue
        text_bbox = field_obj.GetBoundingBox()
        own_layer = field_obj.GetLayer()
        if not has_any_overlap(text_bbox, ref, own_layer, field_obj):
            continue
        fp_bb = fp.GetBoundingBox()
        cx = fp_bb.GetCenter().x; cy = fp_bb.GetCenter().y
        fw2 = fp_bb.GetWidth()//2; fh2 = fp_bb.GetHeight()//2
        tw2 = text_bbox.GetWidth()//2; th2 = text_bbox.GetHeight()//2
        candidates = [
            (cx, cy-fh2-th2-MARGIN), (cx, cy+fh2+th2+MARGIN),
            (cx-fw2-tw2-MARGIN, cy), (cx+fw2+tw2+MARGIN, cy),
            (cx-fw2-tw2-MARGIN, cy-fh2-th2-MARGIN), (cx+fw2+tw2+MARGIN, cy-fh2-th2-MARGIN),
            (cx-fw2-tw2-MARGIN, cy+fh2+th2+MARGIN), (cx+fw2+tw2+MARGIN, cy+fh2+th2+MARGIN),
        ]
        orig_pos = field_obj.GetPosition()
        resolved = False
        for px, py in candidates:
            field_obj.SetPosition(pcbnew.VECTOR2I(int(px), int(py)))
            new_bbox = field_obj.GetBoundingBox()
            if not has_any_overlap(new_bbox, ref, own_layer, field_obj) and in_board(new_bbox):
                resolved = True; moved += 1; break
        if not resolved:
            field_obj.SetPosition(orig_pos)
            field_obj.SetVisible(False)
            hidden_count += 1

# Fill zones
copper_zones = [z for z in board.Zones() if not z.GetIsRuleArea()]
if copper_zones:
    for z in copper_zones:
        z.UnFill()
    filler = pcbnew.ZONE_FILLER(board)
    filler.Fill(board.Zones())

board.Save(params["pcb_path"])
print(json.dumps({"status": "ok", "moved": moved, "hidden": hidden_count,
                    "zones_filled": len(copper_zones)}))
'

tools.description:
Schematic domain router — file lifecycle, components, wires, labels, sheets.

Operations:

# File lifecycle
  create(name) -> {status, name}
      Create a new KiCad schematic.
  load(schematic_path) -> {status, file_path, components}
      Load an existing .kicad_sch file.
  save(schematic_path?) -> {status, file_path}
      Save current schematic; omit schematic_path to save in place.
  validate() -> {status, issues, errors, warnings, details}
      Validate schematic for ERC issues.
  info() -> {status, components, wires, junctions, modified, ...}
      Summary of current schematic state. (was: get_schematic_info)
  clone(new_name?) -> {status, name, components}
      Clone the current schematic (does NOT load the clone).
  backup(suffix=".backup") -> {status, backup_path}
      Create a timestamped backup of the current schematic file.
  check_pin_collisions() -> {status, collision_count, collisions, summary}
      Detect pin-position collisions that cause silent net merges.

# Components — CRUD
  add_component(lib_id, reference, value, position, footprint?, properties?)
      -> {status, reference, lib_id, value, position}
  add_multi_unit_component(lib_id, reference, value, position,
                           units?, footprint?, unit_spacing=15)
      -> {status, reference, total_units, units}   for multi-unit symbols
  remove_component(reference, unit?) -> {status, reference, units_removed}
      unit unspecified removes ALL units sharing this reference (a
      multi-unit symbol like a quad op-amp has one placed component
      per unit); pass unit=N to remove only that one.
  move_component(reference, position, unit?) -> {status, reference, old_position, new_position, unit?}
      If reference resolves to multiple units, unit is required —
      returns an error listing the available units otherwise.
  list_components() -> {status, count, components}
  filter_components(lib_id?, value?, reference?, footprint?) -> {status, count, components}
  components_in_area(x1, y1, x2, y2) -> {status, count, components}
  bulk_update_components(criteria, updates) -> {status, updated}

# Component pins (read-only queries)
  get_component_pin_position(reference, pin_number) -> {status, reference, pin_number, x, y}
  list_component_pins(reference) -> {status, reference, count, pins}
  find_component_connections(project_path, component_ref) -> {status, connections, ...}
      Netlist-based query; reads .kicad_pro + extracts schematic netlist.

# Wires (verb-overlap pair — pick by what you have)
  add_wire(start_pos, end_pos) -> {status, wire_uuid, start, end}
      Add wire by absolute [x, y] coordinates.
  add_wire_between_pins(comp1_ref, pin1, comp2_ref, pin2)
      -> {status, pins, segments, segment_count}
      Add wire by component+pin refs — preferred when you have refs.
  remove_wire(wire_uuid) -> {status, wire_uuid}
  add_junction(position, diameter=0) -> {status, junction_uuid, position}

# Labels (verb-overlap family — pick by intent)
  add_label(text, position, rotation=0, size=1.27)
      -> {status, label_uuid, text, position}
      Net label placed at absolute coordinates.
  add_label_to_pin(reference, pin_number, text, offset=None)
      -> {status, label_uuid, text, reference, pin_number, position}
      Net label attached directly to a pin — preferred when labeling a pin.
      offset omitted/None defaults to 2.54mm; pass offset=0 for a
      literal zero-length stub straight from the pin.
  add_hierarchical_label(text, position, shape="input", rotation=0, size=1.27)
      -> {status, label_uuid, text, shape, position}
      For hierarchical sheet pins, not ordinary net labels.
  connect_pins_with_labels(comp1_ref, pin1, comp2_ref, pin2, net_name)
      -> {status, net_name, labels_created, label_uuids}
      High-level: places matching labels on two pins to connect them via a net.
  remove_label(label_uuid) -> {status, label_uuid}
  edit_label(label_uuid, new_text?, position?, rotation?, size?)
      -> {status, label_uuid, text, position, rotation, size}

# Text annotations
  add_text(text, position, rotation=0, size=1.27)
      -> {status, text_uuid, text, position}
  add_text_box(text, position, sheet_size, rotation=0, font_size=1.27)
      -> {status, textbox_uuid, text, position, size}

# Hierarchical sheets
  add_sheet(name, filename, position, sheet_size) -> {status, sheet_uuid, name, filename, position, size}
  add_sheet_pin(sheet_uuid, name, pin_type, edge, position_along_edge)
      -> {status, pin_uuid, name, pin_type, edge, position_along_edge, sheet_uuid}
      edge: right|bottom|left|top; position_along_edge: mm from reference corner
